-- Demo data for Pivot Charlie. Idempotent; demo tickets are reset on each run.

on conflict (id) do update set name = excluded.name, ticket_prefix = excluded.ticket_prefix,
  bench_address = coalesce(workspaces.bench_address, excluded.bench_address),
  fulfillment_address = coalesce(workspaces.fulfillment_address, excluded.fulfillment_address);

on conflict (id) do nothing;

-- ---------------------------------------------------------------- catalog (demo)
on conflict (id) do update set name = excluded.name, reference = excluded.reference, movement = excluded.movement, case_spec = excluded.case_spec, notes = excluded.notes, is_active = true;

